-- Migration 0018: Catalog Taxonomy v3
-- Additive 21 event categories, 41 service categories (including #33),
-- lettered subcategories, numbered products, event-service selections,
-- content review, eligibility flags, and enquiry plan_items snapshot.
-- Does not modify historical enquiry/quotation/booking/event-record rows.

BEGIN;

ALTER TABLE event_types
  ADD COLUMN IF NOT EXISTS kind text NOT NULL DEFAULT 'occasion';

ALTER TABLE event_types DROP CONSTRAINT IF EXISTS event_types_kind_check;
ALTER TABLE event_types ADD CONSTRAINT event_types_kind_check
  CHECK (kind IN ('occasion', 'service_entry'));

UPDATE event_types SET kind = 'occasion'
 WHERE code IN (
   'engagement','pre_wedding','mehndi','sangeet','wedding','reception',
   'half_saree_dhoti','birthday','cradle_ceremony','house_warming',
   'festival','corporate'
 );

VALUES ('event_catering', 'Catering Services & Manpower', 'Catering services and manpower', 12, 'service_entry')
ON CONFLICT (code) DO UPDATE SET kind = EXCLUDED.kind, display_name = EXCLUDED.display_name;
VALUES ('event_sound_lighting', 'Sound & Lighting Services', 'Sound and lighting services', 13, 'service_entry')
ON CONFLICT (code) DO UPDATE SET kind = EXCLUDED.kind, display_name = EXCLUDED.display_name;
VALUES ('event_photography', 'Photography & Videography', 'Photography and videography', 14, 'service_entry')
ON CONFLICT (code) DO UPDATE SET kind = EXCLUDED.kind, display_name = EXCLUDED.display_name;
VALUES ('event_decoration', 'Event Decoration Services', 'Event decoration services', 15, 'service_entry')
ON CONFLICT (code) DO UPDATE SET kind = EXCLUDED.kind, display_name = EXCLUDED.display_name;
VALUES ('event_venue', 'Event Venue Services', 'Event venue services', 16, 'service_entry')
ON CONFLICT (code) DO UPDATE SET kind = EXCLUDED.kind, display_name = EXCLUDED.display_name;
VALUES ('event_tent_house', 'Tent House Material Supplying', 'Tent-house material supply', 17, 'service_entry')
ON CONFLICT (code) DO UPDATE SET kind = EXCLUDED.kind, display_name = EXCLUDED.display_name;
VALUES ('event_advertising', 'Advertising & Promotions', 'Advertising and promotions', 19, 'service_entry')
ON CONFLICT (code) DO UPDATE SET kind = EXCLUDED.kind, display_name = EXCLUDED.display_name;
VALUES ('event_material', 'Event Material & Equipment Store', 'Event material and equipment store', 20, 'service_entry')
ON CONFLICT (code) DO UPDATE SET kind = EXCLUDED.kind, display_name = EXCLUDED.display_name;
VALUES ('event_fibre', 'Fibre Decoration Manufacturing', 'Fibre decoration manufacturing', 21, 'service_entry')
ON CONFLICT (code) DO UPDATE SET kind = EXCLUDED.kind, display_name = EXCLUDED.display_name;

ALTER TABLE catalog_services
  ADD COLUMN IF NOT EXISTS content_status text NOT NULL DEFAULT 'approved';
ALTER TABLE catalog_services DROP CONSTRAINT IF EXISTS catalog_services_content_status_check;
ALTER TABLE catalog_services ADD CONSTRAINT catalog_services_content_status_check
  CHECK (content_status IN ('source_imported', 'copy_review', 'approved', 'rejected'));
ALTER TABLE catalog_services
  ADD COLUMN IF NOT EXISTS hyderabad_available boolean NOT NULL DEFAULT true;
ALTER TABLE catalog_services
  ADD COLUMN IF NOT EXISTS customer_selectable boolean NOT NULL DEFAULT true;

  code, display_name, source_alias, department_code, entity_kind,
  display_order, branch_id, content_status, hyderabad_available, customer_selectable
) VALUES (
  'indian_festival_event_service',
  'Indian Festival Event Services',
  'INDIAN FESTIVAL EVENT SERVICE',
  'decoration',
  'service',
  33,
  '00000000-0000-4000-8000-000000000001',
  'approved',
  true,
  true
) ON CONFLICT (code) DO UPDATE SET display_order = 33, active = true;

UPDATE catalog_services
   SET hyderabad_available = false, customer_selectable = false
 WHERE code = 'honeymoon_travel';

VALUES ('indian_festival_event_service', 'festival', 1)
ON CONFLICT (service_code, occasion_code) DO NOTHING;

ALTER TABLE catalog_aliases DROP CONSTRAINT IF EXISTS catalog_aliases_entity_type_check;
ALTER TABLE catalog_aliases ADD CONSTRAINT catalog_aliases_entity_type_check
  CHECK (entity_type IN ('occasion', 'service', 'stage', 'department', 'product', 'subcategory', 'selection'));

ALTER TABLE enquiries
  ADD COLUMN IF NOT EXISTS plan_items jsonb NOT NULL DEFAULT '[]'::jsonb;

CREATE TABLE IF NOT EXISTS catalog_subcategories (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  service_code text NOT NULL REFERENCES catalog_services(code),
  letter text NOT NULL,
  source_name text NOT NULL,
  display_name text NOT NULL,
  heading_anomaly text,
  display_order integer NOT NULL DEFAULT 0,
  active boolean NOT NULL DEFAULT true,
  content_status text NOT NULL DEFAULT 'approved'
    CHECK (content_status IN ('source_imported', 'copy_review', 'approved', 'rejected')),
  branch_id uuid NOT NULL REFERENCES branches(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1 CHECK (version > 0),
  UNIQUE (service_code, letter)
);

CREATE INDEX IF NOT EXISTS idx_catalog_subcategories_service
  ON catalog_subcategories (service_code);

CREATE TABLE IF NOT EXISTS catalog_products (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  code text NOT NULL UNIQUE,
  service_code text NOT NULL REFERENCES catalog_services(code),
  subcategory_code text NOT NULL REFERENCES catalog_subcategories(code),
  source_code text NOT NULL,
  source_name text NOT NULL,
  display_name text NOT NULL,
  source_alias text,
  parse_anomaly boolean NOT NULL DEFAULT false,
  placeholder boolean NOT NULL DEFAULT false,
  eligibility_flags jsonb NOT NULL DEFAULT '[]'::jsonb,
  customer_selectable boolean NOT NULL DEFAULT true,
  hyderabad_available boolean NOT NULL DEFAULT true,
  content_status text NOT NULL DEFAULT 'source_imported'
    CHECK (content_status IN ('source_imported', 'copy_review', 'approved', 'rejected')),
  active boolean NOT NULL DEFAULT true,
  display_order integer NOT NULL DEFAULT 0,
  cover_image_url text,
  branch_id uuid NOT NULL REFERENCES branches(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  version integer NOT NULL DEFAULT 1 CHECK (version > 0),
  UNIQUE (service_code, source_code)
);

CREATE INDEX IF NOT EXISTS idx_catalog_products_service
  ON catalog_products (service_code);
CREATE INDEX IF NOT EXISTS idx_catalog_products_subcategory
  ON catalog_products (subcategory_code);
CREATE INDEX IF NOT EXISTS idx_catalog_products_customer
  ON catalog_products (active, customer_selectable, content_status)
  WHERE active AND customer_selectable AND content_status = 'approved';
CREATE INDEX IF NOT EXISTS idx_catalog_products_display_name_trgm
  ON catalog_products USING gin (display_name gin_trgm_ops);
CREATE INDEX IF NOT EXISTS idx_catalog_products_source_name_trgm
  ON catalog_products USING gin (source_name gin_trgm_ops);

CREATE TABLE IF NOT EXISTS event_service_selections (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  event_type_code text NOT NULL REFERENCES event_types(code),
  source_ordinal text NOT NULL,
  source_label text NOT NULL,
  primary_service_code text REFERENCES catalog_services(code),
  mapping_status text NOT NULL
    CHECK (mapping_status IN ('mapped', 'requires_decision', 'unmapped')),
  relevance_order integer NOT NULL DEFAULT 0,
  UNIQUE (event_type_code, source_ordinal)
);

CREATE INDEX IF NOT EXISTS idx_ess_event ON event_service_selections (event_type_code);
CREATE INDEX IF NOT EXISTS idx_ess_service ON event_service_selections (primary_service_code);

CREATE TABLE IF NOT EXISTS catalog_content_revisions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  entity_type text NOT NULL CHECK (entity_type IN ('event_type', 'service', 'subcategory', 'product')),
  entity_code text NOT NULL,
  field text NOT NULL,
  old_value text,
  new_value text,
  actor_user_id uuid REFERENCES app_users(id),
  reason text,
  created_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_catalog_revisions_entity
  ON catalog_content_revisions (entity_type, entity_code, created_at DESC);

DROP TRIGGER IF EXISTS catalog_subcategories_set_updated_at ON catalog_subcategories;
CREATE TRIGGER catalog_subcategories_set_updated_at
BEFORE UPDATE ON catalog_subcategories
FOR EACH ROW EXECUTE FUNCTION set_record_updated_at();

DROP TRIGGER IF EXISTS catalog_products_set_updated_at ON catalog_products;
CREATE TRIGGER catalog_products_set_updated_at
BEFORE UPDATE ON catalog_products
FOR EACH ROW EXECUTE FUNCTION set_record_updated_at();

